{
  "root_causes": [
    {
      "service": "attractions",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "trace", "sql": "SELECT (SELECT count(*) FROM normal_traces WHERE service_name='attractions') AS normal_attractions_spans, (SELECT count(*) FROM abnormal_traces WHERE service_name='attractions') AS abnormal_attractions_spans, (SELECT count(*) FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /cinema' AND attr_status_code='Error') AS cinema_500s", "claim": "Attractions emits no spans in the abnormal period, while frontend /cinema requests all fail with 500."},
        {"kind": "trace", "sql": "SELECT p, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 AS p50_ms FROM (SELECT 'norm' p, * FROM normal_traces UNION ALL SELECT 'abn', * FROM abnormal_traces) WHERE span_name IN ('attractions.Attractions/NearbyCinema','attractions.Attractions/NearbyMus','attractions.Attractions/NearbyRest') GROUP BY ALL ORDER BY 2,1", "claim": "Frontend client calls to attractions Nearby* operations disappear entirely in the abnormal period."},
        {"kind": "metric", "sql": "SELECT p, avg(value) AS avg_cpu, min(value) AS min_cpu, max(value) AS max_cpu, count(*) n FROM (SELECT 'norm' p, * FROM normal_metrics UNION ALL SELECT 'abn', * FROM abnormal_metrics) WHERE metric='k8s.pod.cpu.usage' AND attr_k8s_pod_name LIKE 'attractions-6cfc749b67%' GROUP BY p", "claim": "Attractions pod CPU usage drops to about a third of normal, consistent with no request processing."}
      ]
    },
    {
      "service": "user",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT p, attr_k8s_pod_name pod, metric, avg(value) avgv, min(value) minv, max(value) maxv, count(*) n FROM (SELECT 'abn' p, * FROM abnormal_metrics UNION ALL SELECT 'norm', * FROM normal_metrics) WHERE metric='k8s.container.ready' AND attr_k8s_pod_name LIKE 'user-69b8b87b86%' GROUP BY ALL ORDER BY p", "claim": "The user pod reports container ready=0 throughout the abnormal window, versus ready=1 normally."},
        {"kind": "metric", "sql": "SELECT p, attr_k8s_pod_name pod, avg(value) avgv, min(value) minv, max(value) maxv FROM (SELECT 'abn' p, * FROM abnormal_metrics UNION ALL SELECT 'norm', * FROM normal_metrics) WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'user-69b8b87b86%' GROUP BY ALL ORDER BY p", "claim": "User pod restart counter climbs to 10-12 in the abnormal period, against a steady 7 normally."},
        {"kind": "trace", "sql": "SELECT p, service_name, attr_span_kind, span_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE span_name='user.User/CheckUser' GROUP BY ALL ORDER BY p, service_name", "claim": "user.User/CheckUser server spans vanish in the abnormal period; frontend client calls all error at about 14 microseconds."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "user",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n FROM abnormal_traces WHERE span_name IN ('HTTP /user','user.User/CheckUser') GROUP BY ALL ORDER BY 1,2,3", "claim": "Frontend HTTP /user requests return 500 because the user.User/CheckUser calls fail immediately."}
      ]
    },
    {
      "from": "attractions",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, approx_quantile(duration,0.5)/1e6 AS p50_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /cinema','HTTP /museums','HTTP /restaurants') GROUP BY ALL ORDER BY 2", "claim": "Frontend /cinema, /museums and /restaurants all return errors in about 0.04 ms, with no attractions calls beneath them."}
      ]
    }
  ]
}
